"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["16904"],{76682(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.tipo_de_ato_nao_congela_configuracao","status":422,"titulo":"O ato que cria a vers\xe3o da configura\xe7\xe3o precisa ser de um tipo que congela configura\xe7\xe3o"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.tipo_de_ato_nao_congela_configuracao","requisitos":["UNI-REQ-0019"],"oQueAconteceu":["Publicar ou retificar um processo seletivo sempre congela uma nova\\n`VersaoConfiguracao` (UNI-REQ-0019) \u2014 n\xe3o \xe9 uma caracter\xedstica opcional do ato, \xe9 o\\nque a transi\xe7\xe3o faz por defini\xe7\xe3o. O tipo de ato declarado no comando n\xe3o\\nest\xe1 marcado, no cat\xe1logo de Publica\xe7\xf5es, como um tipo que congela\\nconfigura\xe7\xe3o (`congela_configuracao`).","A regra n\xe3o compara o c\xf3digo do tipo contra uma lista fixa em c\xf3digo \u2014\\npergunta ao cat\xe1logo se aquele tipo congela. Um tipo de ato pensado para\\noutro prop\xf3sito (por exemplo, uma comunica\xe7\xe3o informativa, sem efeito sobre a\\nconfigura\xe7\xe3o) n\xe3o serve para publicar nem retificar, mesmo que o c\xf3digo exista\\ne esteja vigente.","Sem esta confer\xeancia, a inconsist\xeancia n\xe3o ficaria parada: a pr\xf3xima\\nretifica\xe7\xe3o, com um tipo congelante de verdade, seria recusada por classe de\\nato divergente \u2014 deixando a retifica\xe7\xe3o publicada sem ato correspondente."],"comoResolver":["Use um tipo de ato marcado como congelante no cadastro de Publica\xe7\xf5es para\\npublicar ou retificar. Se o tipo de ato que voc\xea pretendia usar n\xe3o deveria\\ncongelar configura\xe7\xe3o, ele n\xe3o \xe9 adequado para este comando \u2014 publica\xe7\xf5es e\\nretifica\xe7\xf5es de processo seletivo sempre exigem um tipo congelante, por\\ndefini\xe7\xe3o de UNI-REQ-0019."],"ondeAparece":["Publica\xe7\xe3o do processo seletivo","Retifica\xe7\xe3o do processo seletivo","Fechamento de retifica\xe7\xe3o"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);